import pytest

@pytest.fixture
def registry():
    reg = {}                               # fresh state per test
    reg["relu"] = lambda x: max(x, 0)
    return reg

def test_register(registry):
    assert "relu" in registry

def test_lookup(registry):
    assert registry["relu"](-2) == 0
